# ═══════════ EXECUTE ═══════════
conn = sqlite3.connect(DB_PATH)
cursor = conn.cursor()

# Get categories
cursor.execute("SELECT id, slug FROM Category ORDER BY \"order\"")
cats = {row[1]: row[0] for row in cursor.fetchall()}

created = 0
skipped = 0
errors = 0

for i, a in enumerate(articles):
    cat_id = cats.get(a['cat'])
    if not cat_id:
        print(f"SKIP: no category {a['cat']}")
        skipped += 1
        continue

    slug = slugify(a['title'])
    
    cursor.execute("SELECT id FROM Article WHERE slug = ?", (slug,))
    if cursor.fetchone():
        skipped += 1
        continue

    cover = img(a['cat'], i % 5)
    now = datetime.utcnow().isoformat()
    
    try:
        cursor.execute("""
            INSERT INTO Article (id, title, slug, excerpt, content, coverImage, published, featured, authorName, categoryId, viewCount, createdAt, updatedAt)
            VALUES (?, ?, ?, ?, ?, ?, 1, 0, 'IICP', ?, 0, ?, ?)
        """, (
            f"art_{slug[:30]}_{i}", a['title'], slug, a['excerpt'], a['content'],
            cover, cat_id, now, now
        ))
        created += 1
        print(f"✓ [{a['cat']}] {a['title'][:60]}...")
    except Exception as e:
        if 'UNIQUE' in str(e):
            skipped += 1
        else:
            errors += 1
            print(f"✗ Error: {a['title'][:40]}... - {e}")

conn.commit()

print(f"\n{'='*50}")
print(f"Created: {created}, Skipped: {skipped}, Errors: {errors}")
print(f"\nFinal counts:")

cursor.execute("""
    SELECT c.name, COUNT(a.id) 
    FROM Category c 
    LEFT JOIN Article a ON a.categoryId = c.id 
    GROUP BY c.id 
    ORDER BY c."order"
""")
for row in cursor.fetchall():
    print(f"  {row[0]}: {row[1]} articles")

conn.close()